// [rand.req.eng] Table 127, x == y: "With S_x and S_y as the infinite sequences of values that
// would be generated by repeated future calls to x() and y(), respectively, returns true if
// S_x = S_y; else returns false." For philox_engine the future sequence is determined by K, X and
// i ([rand.eng.philox]/3; /8: "The stream extraction operator can reconstruct Y from K and X"), so
// two engines at i == n - 1 with equal K and X compare equal whatever their buffered Y.
#include <random>
#include "check.hpp"

int main() {
  // set_counter sets i = n - 1 (/11): the position within the current block is discarded.
  std::philox4x32 d(3), d0(3);
  d();
  d.set_counter({0, 0, 0, 0});
  for (int k = 0; k < 8; ++k) {
    std::philox4x32 x = d, y = d0;
    CHECK(x() == y());
  }
  CHECK(d == d0);

  // After a full block the engine equals one whose counter was set to the next block.
  std::philox4x32 s1(3), s2(3);
  s1.discard(4);
  s2.set_counter({0, 0, 0, 1});
  CHECK(s1 == s2);
  for (int k = 0; k < 8; ++k) CHECK(s1() == s2());
  CHECK(s1 == s2);

  std::philox4x64 t1, t2;
  t1.discard(8);
  t2.set_counter({0, 0, 0, 2});
  CHECK(t1 == t2);
}
